    if plain:
        parts.append(plain)
    for item in row.get("lists") or []:
        if not isinstance(item, dict):
            continue
        heading = (item.get("text") or "").strip()
        body = html_to_readable(item.get("content") or "")
        if heading and body:
            parts.append(f"{heading}\n{body}")
        elif body:
            parts.append(body)
    extra = html_to_readable(row.get("additional") or "")
    if extra:
        parts.append(extra)
    return "\n\n".join(parts)

